"""Pruebas del ejercicio m21-e8."""

from importlib import metadata

import pytest

import verificar_entorno as v

BLOQUEO = """\
#
# This file is autogenerated by pip-compile with Python 3.12
#
--index-url https://pypi.org/simple

duckdb==1.1.3
    # via conciliacion (pyproject.toml)
numpy==2.1.2 \\
    --hash=sha256:aaaa \\
    --hash=sha256:bbbb
    # via pandas
pandas==2.2.3
Python_Dateutil==2.9.0.post0
tzdata==2024.2 ; sys_platform == 'win32'
uvicorn[standard]==0.30.6
zope.interface==7.0
"""


def test_normalizar():
    assert v.normalizar("Python_Dateutil") == "python-dateutil"
    assert v.normalizar("zope.interface") == "zope-interface"
    assert v.normalizar("A--B__C..D") == "a-b-c-d"


def test_leer_bloqueo():
    assert v.leer_bloqueo(BLOQUEO) == {
        "duckdb": "1.1.3", "numpy": "2.1.2", "pandas": "2.2.3", "python-dateutil": "2.9.0.post0",
        "tzdata": "2024.2", "uvicorn": "0.30.6", "zope-interface": "7.0",
    }


def test_bloqueo_con_rangos_es_error():
    with pytest.raises(ValueError, match="pandas>=2.2"):
        v.leer_bloqueo("duckdb==1.1.3\npandas>=2.2\n")


def test_comparar():
    bloqueo = {"duckdb": "1.1.3", "numpy": "2.1.2", "pandas": "2.2.3"}
    instaladas = {"duckdb": "1.1.3", "numpy": "2.0.0", "requests": "2.32.3", "pip": "24.2", "setuptools": "75", "wheel": "0.44"}
    assert v.comparar(bloqueo, instaladas) == {
        "faltan": ["pandas"], "distintas": [("numpy", "2.1.2", "2.0.0")], "sobran": ["requests"]}
    assert v.comparar({}, {}) == {"faltan": [], "distintas": [], "sobran": []}


def test_instaladas_reales():
    r = v.instaladas()
    assert r["pytest"] == metadata.version("pytest")
    assert all(nombre == v.normalizar(nombre) for nombre in r)


@pytest.fixture
def entorno_falso(monkeypatch):
    monkeypatch.setattr(v, "instaladas", lambda: {"duckdb": "1.1.3", "numpy": "2.1.2", "pandas": "2.2.3", "rich": "13.9"})


def test_main_igual(tmp_path, entorno_falso, capsys):
    lock = tmp_path / "requirements.lock"
    lock.write_text("duckdb==1.1.3\nnumpy==2.1.2\npandas==2.2.3\n", encoding="utf-8")
    assert v.main([str(lock)]) == 0
    salida = capsys.readouterr().out
    assert "✅ Entorno igual al bloqueo (3 paquetes)" in salida
    assert "⚠️  Sobra: rich==13.9" in salida
    assert v.main([str(lock), "--estricto"]) == 1


def test_main_distinto(tmp_path, entorno_falso, capsys):
    lock = tmp_path / "requirements.lock"
    lock.write_text("duckdb==1.1.3\nnumpy==2.2.0\npandas==2.2.3\npolars==1.9.0\nrich==13.9\n", encoding="utf-8")
    assert v.main([str(lock)]) == 1
    salida = capsys.readouterr().out
    assert "❌ Falta: polars==1.9.0" in salida
    assert "❌ Distinta: numpy (bloqueo 2.2.0, instalada 2.1.2)" in salida
    assert "✅" not in salida


def test_main_sin_archivo(tmp_path, capsys):
    assert v.main([str(tmp_path / "no_existe.lock")]) == 2
    assert "no_existe.lock" in capsys.readouterr().err
